contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depAmount, uint withdrawAmount) public payable {
        require(depAmount > 0, "deposit must be positive");
        require(withdrawAmount > 0, "withdraw must be positive");
        require(address(this).balance >= depAmount, "not enough balance to deposit");

        uint beforeContractBalance = address(c).balance;
        uint beforeCredit = c.credit(address(this));

        c.deposit{value: depAmount}();

        uint afterDepositContractBalance = address(c).balance;
        uint afterDepositCredit = c.credit(address(this));

        uint beforeWithdrawCallerBalance = address(this).balance;

        bool withdrawReverted;
        try c.withdrawAll() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint afterContractBalance = address(c).balance;
        uint afterCredit = c.credit(address(this));
        uint afterCallerBalance = address(this).balance;

        assert(
            afterDepositCredit >= depAmount &&
            afterDepositContractBalance == beforeContractBalance + depAmount &&
            (
                withdrawReverted
                    ? (afterContractBalance == afterDepositContractBalance && afterCredit == afterDepositCredit && afterCallerBalance == beforeWithdrawCallerBalance)
                    : (afterCallerBalance >= beforeWithdrawCallerBalance + withdrawAmount &&
                       afterContractBalance <= afterDepositContractBalance - withdrawAmount &&
                       afterCredit == 0)
            )
        );
    }

    receive() external payable {}
}

